"""Generate README.md from the result files. Do not edit README.md by hand.

Usage: python -m fcp.readme
"""

import json
import os

from fcp.fetch import MANIFEST, ROOT
from fcp.learn import results_path
from fcp.cite import citations, software_citation
from fcp.site import note_2008
from fcp.sources import NOT_COVERED, REJECTED, SOFTWARE, SOURCES
from fcp.stats import CORR_OUT, SUMMARY_OUT

README = os.path.join(ROOT, "README.md")
ROUNDTRIP = os.path.join(ROOT, "results", "hydradb_float_roundtrip.json")


def load(p):
    with open(p, encoding="utf-8") as f:
        return json.load(f)


def f2(v):
    return "%.2f" % v


def render():
    r = load(results_path())
    s = load(SUMMARY_OUT)
    corr = load(CORR_OUT)
    man = {e["id"]: e for e in load(MANIFEST)["files"]}
    rt = load(ROUNDTRIP) if os.path.exists(ROUNDTRIP) else None
    sc = r["scores_co2"]
    ex = s["excluding_2020_2021"]
    hy = r["hydradb"]
    archived = os.path.join(ROOT, "results", "archive", "run3_learning_results.json")
    prev = load(archived) if os.path.exists(archived) else None
    t = r["tuning"]
    names = [("graph", "HydraDB graph, refit every year"), ("no_change", "No change"),
             ("knn", "Vector-store k-NN (k=%d, window %s)" % (t["knn_k"], t["knn_window"] or "all")),
             ("frozen_graph", "Frozen graph (weights fixed after 2004)"), ("direct_regression", "Direct regression, no graph (reported only)")]
    L = []
    a = L.append
    a("# Fuel, Cars & Pollution: a HydraDB graph that refits its own links every year")
    a("")
    a("HydraDB Hackathon, Track 1 (\"a graph that improves itself, sharper every run\").")
    a("")
    a("Crude oil → gasoline → fuel use → U.S. transport CO2, with miles driven and electric-car adoption feeding in. "
      "Each link's strength is stored in a self-hosted HydraDB graph and refit every year, so each correction changes the next prediction. "
      "It is tested walk-forward, on years not used to design it, against a vector-store-style k-nearest-neighbour lookup and a \"no change\" guess.")
    a("")
    a("- Live app: https://fuel-cars-pollution.netlify.app (private until the author opens it; static site in `site/`).")
    a("- Walkthrough video: not recorded yet.")
    a("")
    a("> README generated by `python -m fcp.readme` from `results/*.json`. Do not edit numbers by hand.")
    a("")
    a("## Result first, weaknesses first")
    a("")
    a("**Pre-registered verdict: %s** (all four parts; rule in [PREREGISTRATION.md](PREREGISTRATION.md), committed before any run: `%s`)." % (
        r["verdict"], (r["preregistration_commit"] or "").split(" ")[0][:12]))
    a("")
    a("Before reading that as a win:")
    a("")
    def vs(m):
        return ("**loses** to" if ex["graph"] > ex[m] else "beats") + " %s (%s)" % ({"no_change": "no change", "knn": "k-NN", "frozen_graph": "its frozen version"}[m], f2(ex[m]))
    a("- **Without 2020 and 2021** (n = %d) the graph's MAE is %s pp: it %s, %s, and %s." % (
        ex["n"], f2(ex["graph"]), vs("no_change"), vs("knn"), vs("frozen_graph")))
    b = r["bootstrap_95"]
    zero = all(v["low"] <= 0 <= v["high"] for v in b.values())
    a("- **%s 95%% bootstrap interval of the MAE difference includes zero** (graph minus no change %s to %s; minus k-NN %s to %s; minus frozen %s to %s). n = %d holdout years." % (
        "Every" if zero else "Not every",
        f2(b["graph_minus_no_change"]["low"]), f2(b["graph_minus_no_change"]["high"]), f2(b["graph_minus_knn"]["low"]), f2(b["graph_minus_knn"]["high"]),
        f2(b["graph_minus_frozen_graph"]["low"]), f2(b["graph_minus_frozen_graph"]["high"]), s["holdout_n"]))
    a("- Year by year the graph beats no change in %d of %d years and k-NN in %d of %d." % (
        s["graph_wins_by_year"]["no_change"], s["holdout_n"], s["graph_wins_by_year"]["knn"], s["holdout_n"]))
    a("- Largest misses: %s.%s" % (", ".join("%d (%s pp)" % (e["year"], f2(e["abs_error"])) for e in s["largest_graph_errors"]), note_2008(r)))
    a("- The EV share → fuel use link is not identified: learned from %d years, its weight swung between %s and %s after 2012." % (
        s["ev_link_weight_range_2012_on"]["ev_years_used"], f2(s["ev_link_weight_range_2012_on"]["min"]), f2(s["ev_link_weight_range_2012_on"]["max"])))
    if hy:
        a("- Parity between HydraDB and the in-memory store passed the 1e-9 limit but is **not bit-identical**: max difference %.3g pp over %d predictions%s." % (
            hy["parity"]["max_abs_diff"], hy["parity"]["compared_values"],
            (" (HydraDB returned %d of %d test floats one ULP off; a likely cause, not proven)" % (rt["mismatches"], rt["values_tested"])) if rt else ""))
    else:
        a("- **No HydraDB run in this result file** (memory-only run): the parity part of the rule is not met.")
    v, e11 = s["vmt_check"], s["excluding_2011"]
    a("- **Data problem in a pre-registered input.** FHWA's VM-203 table puts %d vehicle-miles %+.2f%% above FHWA's own VM-1 table; the other %d years agree within %.2f%%." % (
        v["worst_year"], v["worst_gap_pct"], v["years_compared"] - 1, v["max_other_gap_pct"])
      + ((" That makes the %d miles change %+.2f instead of %+.2f. The official run keeps VM-203 as pre-registered. Scored without %d (n = %d): graph %s, no change %s, k-NN %s, frozen %s." % (
          v["next_year"], v["next_change_vm203"], v["next_change_vm1"], v["next_year"], e11["n"], f2(e11["graph"]), f2(e11["no_change"]), f2(e11["knn"]), f2(e11["frozen_graph"])))
         if "next_year" in v else ""))
    a("- On the design years (1982–2004) k-NN was better than the graph: MAE %s vs %s (n=%d)." % (
        f2(sc["knn"]["design_mae"]), f2(sc["graph"]["design_mae"]), sc["graph"]["design_n"]) if sc["knn"]["design_mae"] < sc["graph"]["design_mae"] else
      "- On the design years (1982–2004) the graph was better than k-NN: MAE %s vs %s." % (f2(sc["graph"]["design_mae"]), f2(sc["knn"]["design_mae"])))
    a("- Inputs are today's revised figures, not the first-release values that existed at the time. A true real-time nowcast would see noisier inputs; this test does not measure that.")
    a("- 2009 and 2010 are not scored: FHWA's VM-203 table, the pre-registered miles source, marks 2009 as unavailable.")
    a("- Reported graph scores are the HydraDB run's own predictions (`graph_predictions_from` in the result file: %s)." % r.get("graph_predictions_from", "memory"))
    a("")
    a("| Model | Holdout MAE (pp) | n | Without 2020–21 (n=%d) | Design MAE (n=%d) |" % (ex["n"], sc["graph"]["design_n"]))
    a("|---|---:|---:|---:|---:|")
    for k, label in names:
        a("| %s | %s | %d | %s | %s |" % (label, f2(sc[k]["holdout_mae"]), sc[k]["holdout_n"], f2(ex[k]), f2(sc[k]["design_mae"])))
    a("")
    a("MAE of the predicted yearly change in U.S. transportation-sector CO2 (EIA), in percentage points of 100·ln change. "
      "Design years 1982–2004 picked the settings (λ = %s for the graph; k = %d, window = %s for k-NN); holdout years 2005–2024 were scored once." % (
          t["graph_lambda"], t["knn_k"], t["knn_window"] or "all"))
    a("")
    a("| Rule part | Threshold | Value | Margin | Result |")
    a("|---|---|---:|---:|---|")
    for p in r["rule"]:
        val = ("%.3g" % p["value"]) if p["part"] == 1 else f2(p["value"])
        mar = ("%.3g" % p["margin"]) if p["part"] == 1 else f2(p["margin"])
        a("| %d. %s | %s | %s | %s | %s |" % (p["part"], p["name"], p["threshold"], val, mar, "PASS" if p["pass"] else "FAIL"))
    a("")
    sec = r["secondary_targets"]
    a("Secondary targets (graph vs no change, holdout MAE): fuel use %s vs %s (n=%d); gasoline price from crude %s vs %s (n=%d)." % (
        f2(sec["FuelUse"]["graph_holdout_mae"]), f2(sec["FuelUse"]["no_change_holdout_mae"]), sec["FuelUse"]["n"],
        f2(sec["Gasoline"]["graph_holdout_mae"]), f2(sec["Gasoline"]["no_change_holdout_mae"]), sec["Gasoline"]["n"]))
    a("")
    a("## What it is")
    a("")
    a("A nowcast: when a year closes, the graph estimates how much U.S. transport CO2 changed, before the official figure is final. "
      "It knows that year's crude oil price, gasoline price, vehicle-miles and the electric share of new car sales. It does not know fuel use or CO2 yet.")
    a("")
    a("1. **Predict.** Query HydraDB for the links pointing into `FuelUse`, read their weights, predict fuel use; then read the links into `CO2` and push the predicted fuel use one more hop.")
    a("2. **Correct.** When the real figures arrive, refit each target's weights by recursive least squares with forgetting, and write them back to HydraDB with a per-year history node.")
    a("3. **Repeat** next year with the corrected weights.")
    a("")
    a("The site also shows the data behind it (fuel prices, miles driven, vehicles per 1,000 people, EV share, transport CO2 and highway-vehicle pollutants) and correlations of year-over-year changes.")
    a("")
    a("## How HydraDB is used")
    a("")
    a("- Engine: `hydra-db/hydradb` v0.4.0 `graph-node`, self-hosted, local mode (`CLOUD_PROVIDER=local`), started by `scripts/run_hydradb.sh` with a new empty store, a new random token, `GRAPH_USAGE_REPORT_ENABLED=false`, and all listeners bound to 127.0.0.1. The engine is not in this repository.")
    a("- Graph: `Variable` nodes (Crude, Gasoline, VMT, EVShare, FuelUse, CO2); `Link` nodes holding the learned weight; `Fit` nodes holding each target's intercept and RLS covariance; `LinkState` history nodes (one per link per year); `Prediction` nodes. Edges: `FEEDS`, `INTO`, `FITS`, `HISTORY`, `OF`.")
    a("- Links are nodes because v0.4.0 deduplicates edges on (source, target, type): an edge cannot carry a weight that changes and keeps history.")
    a("- Each prediction is a graph walk: `MATCH (t {id: $id})<-[:INTO]-(s) RETURN s.id`, then anchored id reads of each link and fit node.")
    a("- Writes use the documented shapes: `UNWIND $rows AS row MERGE (n {id: row.id}) SET n:Label, n.p = row.p` for nodes (labels cannot sit in an UNWIND pattern), `UNWIND … CREATE` for edges, `MATCH (n {id: $id}) SET …` for updates.")
    if hy:
        a("- This run: %d HTTP queries in %s s; graph after the run: %s." % (hy["http_requests"], hy["seconds"], ", ".join("%d %s" % (v, k) for k, v in hy["node_counts"].items())))
    a("- Same code on an in-memory store gives the parity check.")
    a("")
    a("Engine notes found while building (v0.4.0):")
    a("")
    a("- `graph-node` binds to 0.0.0.0 by default; `GRAPH_HTTP_ADDR`, `GRAPH_BOLT_ADDR` and `GRAPH_ADMIN_ADDR` set it to loopback.")
    if rt and hy:
        a("- Floats do not always round-trip exactly: %d of %d test values came back one ULP off (`results/hydradb_float_roundtrip.json`). That is a likely cause of the %.3g pp gap between the HydraDB and in-memory predictions (not proven). Storing exact bit patterns (for example hex strings) would rule it out." % (
            rt["mismatches"], rt["values_tested"], hy["parity"]["max_abs_diff"]))
    a("- `count(n)` is rejected; `count(*)` and `count(n.prop)` work.")
    a("- Node ids must be non-negative integers.")
    a("")
    a("## Pre-registered rule")
    a("")
    a("Full text: [PREREGISTRATION.md](PREREGISTRATION.md). It was committed before the first run and not edited afterwards. PASS needs all four:")
    a("")
    a("1. HydraDB and in-memory predictions agree within 1e-9 pp.")
    a("2. Graph holdout MAE ≤ 0.90 × no-change MAE.")
    a("3. Graph holdout MAE ≤ 0.90 × k-NN MAE.")
    a("4. Graph holdout MAE < frozen-graph MAE (refitting must help).")
    a("")
    a("Run history, for honesty:")
    a("")
    a("1. Runs 1 and 2 crashed in the HydraDB step (a batching bug in this project's store code, then `count(n)` being unsupported) before any holdout score was computed or printed.")
    if prev:
        a("2. Run 3 completed (archived in `results/archive/run3_learning_results.json`). An independent code review then found that its k-NN baseline only used neighbour years that also had every other input, which PREREGISTRATION.md does not ask for. Run 3 tuned k-NN to k = %d, window %s, and scored it %s on the holdout." % (
            prev["tuning"]["knn_k"], prev["tuning"]["knn_window"] or "all", f2(prev["scores_co2"]["knn"]["holdout_mae"])))
        a("3. Run 4, the result above, implements the pre-registered k-NN wording exactly and re-tunes it on the design years only: k = %d, window %s, holdout %s. The graph, the rule, the periods and the metric did not change. Run 4 also reports the HydraDB run's own predictions." % (
            r["tuning"]["knn_k"], r["tuning"]["knn_window"] or "all", f2(sc["knn"]["holdout_mae"])))
    a("")
    a("## Correlations (year-over-year changes)")
    a("")
    a("Co-movement only; not cause. Flagged values excluded; same region and years.")
    a("")
    a("| X | Y | Region | n | Years | Pearson r | Spearman ρ |")
    a("|---|---|---|---:|---|---:|---:|")
    for c in corr:
        a("| %s | %s | %s | %d | %s–%s | %s | %s |" % (c["x_label"], c["y_label"], c["region"], c["n"], c["first_year"], c["last_year"],
                                                       f2(c["pearson_r"]) if "pearson_r" in c else "n/a", f2(c["spearman_rho"]) if "spearman_rho" in c else "n/a"))
    a("")
    a("## Data")
    a("")
    a("Every number comes from a downloaded file; URL, retrieval time and SHA-256 are in `data/manifest.json`, and `tests/test_data.py` re-reads the raw files.")
    a("")
    a("| Source | Licence | Retrieved (UTC) | SHA-256 |")
    a("|---|---|---|---|")
    for src in SOURCES:
        m = man[src["id"]]
        a("| [%s](%s) | %s | %s | `%s…` |" % (src["title"], src["url"], src["licence"], m["retrieved_at_utc"], m["sha256"][:16]))
    a("")
    a("Flags: the latest year of each EIA Monthly Energy Review table is marked provisional; EPA highway-vehicle values for 2024–2025 are marked carried forward (EPA's workbook notes say those years repeat the 2023 inventory except power-plant NOx/SO2 and fires; a test checks the highway values equal 2023); calendar years with fewer than 12 months of Ember data are marked partial. Flagged values are shown but left out of correlations and scoring.")
    a("")
    a("### How to cite the data")
    a("")
    a("Release and update dates are read from the downloaded files; CC BY 4.0 sources list the changes made, as that licence requires.")
    a("")
    for ct in citations():
        a("- %s Changes made: %s" % (ct["text"], ct["changes"]))
    a("")
    a("Considered and not used:")
    a("")
    for x in REJECTED:
        a("- **%s**: %s" % (x["name"], x["reason"]))
    a("")
    a("Not covered:")
    a("")
    for x in NOT_COVERED:
        a("- **%s**: %s" % (x["item"], x["why"]))
    a("")
    a("## Limitations")
    a("")
    a("- Small sample: %d holdout years; the intervals above are wide." % s["holdout_n"])
    a("- The author knew the broad history of the holdout years (2008, 2020) even though settings were picked on 1982–2004 only.")
    a("- Inputs are revised (final) values from today's files, not real-time vintages; real-time accuracy is unmeasured.")
    a("- Nowcasting is narrow: EIA publishes the real CO2 figure within months. The value shown is the learning loop, not a forecast product.")
    a("- U.S. only for the learning loop. World series are shown but not modelled.")
    a("- The \"what the links imply\" calculator on the site is arithmetic on the final weights; it was not tested as a scenario model.")
    a("- The k-NN baseline is one reasonable plain-store design (same inputs, standardised, RMS distance over shared dimensions). Other designs could score differently.")
    a("")
    a("## Reproduce")
    a("")
    a("```bash")
    a("python -m pip install -r requirements.txt")
    a("python -m fcp.fetch        # download files, write data/manifest.json")
    a("python -m fcp.parse        # data/processed/series.json")
    a("bash scripts/run_hydradb.sh <path-to-graph-node> .hydradb/token   # inside WSL/Linux, separate shell")
    a("python -m fcp.experiment   # pre-registered run -> results/learning_results.json")
    a("python -m fcp.roundtrip    # float round-trip check")
    a("python -m fcp.stats        # correlations and summary")
    a("python -m fcp.site         # static site in site/")
    a("python -m fcp.readme       # this file")
    a("python -m pytest -q        # tests, data check, privacy scan")
    a("```")
    a("")
    a("Re-downloading gives today's files; the committed raw files and their hashes are what these results used.")
    a("")
    a("## Software and licences")
    a("")
    a("All software is open source except the HydraDB engine, which is source-available under the Elastic License 2.0 and was used under the hackathon's terms. The site loads nothing from other websites (checked by `tests/test_generated.py`). `tests/test_licences.py` checks each package licence below against the installed metadata. The share image's text is set in Aileron Regular (CC0 1.0), as shipped inside Pillow.")
    a("")
    a("| Software | Licence | Used for |")
    a("|---|---|---|")
    for x in SOFTWARE:
        a("| [%s](%s) | %s | %s |" % (x["name"], x["url"], x["licence"], x["role"]))
    a("")
    a("Cite the graph engine as: %s" % software_citation())
    a("")
    a("## Licence")
    a("")
    a("Code: MIT (see `LICENSE`). Data keeps its publishers' licences (see above). HydraDB is Elastic License 2.0 and is not included or redistributed.")
    a("")
    a("## Names and trademarks")
    a("")
    a("This is an independent entry to the HydraDB Hackathon. It is not made, sponsored or endorsed by HydraDB; the name is used only to identify the engine and the hackathon. Data publishers are named only to cite their data.")
    a("")
    return "\n".join(L)


LAUNCH = os.path.join(ROOT, "docs", "LAUNCH.md")


def render_launch():
    """Draft launch material for the author. Nothing here is posted or submitted."""
    r = load(results_path())
    s = load(SUMMARY_OUT)
    sc = r["scores_co2"]
    ex = s["excluding_2020_2021"]
    hy = r["hydradb"]
    g, nc, kn, fr = (f2(sc[k]["holdout_mae"]) for k in ("graph", "no_change", "knn", "frozen_graph"))
    L = []
    a = L.append
    a("# Launch kit (drafts for the author; nothing here has been posted or submitted)")
    a("")
    a("> Generated by `python -m fcp.readme` from `results/*.json`. Numbers update with the results.")
    a("")
    a("## Needs the author's explicit go, one action at a time")
    a("")
    a("1. Host the static site (`site/` folder; any static host works, no build step).")
    a("2. Make the GitHub repository public.")
    a("3. Record the Loom walkthrough.")
    a("4. Submit the hackathon form.")
    a("5. Publish the social post tagging HydraDB.")
    a("")
    a("## Who it is for")
    a("")
    a("- Energy and climate reporters who need a quick, sourced read on whether transport emissions are moving with fuel prices and driving.")
    a("- Analysts who want a model that shows its own learning: every link weight and every prediction is a node with history.")
    a("- Teachers: one page that walks from crude oil to tailpipe CO2 with official data and an honest test.")
    a("")
    a("## Loom outline (about 3 minutes)")
    a("")
    a("1. **0:00 Problem.** Fuel prices, miles driven, EVs and CO2 all move together, but which links matter, and do they change? Static models go stale.")
    a("2. **0:30 The graph.** Show the diagram. Each arrow is a node in HydraDB holding its weight; every year the weights are refit and a history node is written.")
    a("3. **1:00 The rule.** Show PREREGISTRATION.md and its commit time: written before any run, four parts, 10% margins.")
    a("4. **1:30 The result.** Verdict %s. Holdout MAE: graph %s pp, no change %s, k-NN %s, frozen %s (n=%d)." % (r["verdict"], g, nc, kn, fr, sc["graph"]["holdout_n"]))
    a("5. **2:00 The honest part.** Without 2020–21 the graph scores %s vs no change %s, k-NN %s, frozen %s. Intervals include zero. Say it plainly." % (
        f2(ex["graph"]), f2(ex["no_change"]), f2(ex["knn"]), f2(ex["frozen_graph"])))
    if hy:
        a("6. **2:30 HydraDB under the hood.** %d queries per full run; links as nodes because edges dedupe on (source, target, type); parity vs in-memory within %.3g pp, with the one-ULP float finding." % (
            hy["http_requests"], hy["parity"]["max_abs_diff"]))
    a("7. **2:50 Close.** Sources page: every number traced to a file with its SHA-256.")
    a("")
    a("## Social post draft")
    a("")
    a("Write the HydraDB handle in yourself when posting.")
    a("")
    a("```text")
    a("I built a graph that refits its own links every year: crude oil -> gasoline -> fuel use -> US transport CO2, with miles driven and EVs feeding in.")
    a("")
    a("Link strengths live in a self-hosted HydraDB graph. Rule written before the first run.")
    a("")
    a("Holdout 2005-2024: graph MAE %s pp vs %s for 'no change' and %s for a vector-store k-NN. Verdict: %s." % (g, nc, kn, r["verdict"]))
    both = ex["graph"] > ex["no_change"] and ex["graph"] > ex["knn"]
    a("The catch: without 2020-21 it scores %s and %s. I'm publishing that too." % (
        f2(ex["graph"]), "loses to both" if both else "the gap narrows to %s vs %s vs %s" % (f2(ex["graph"]), f2(ex["no_change"]), f2(ex["knn"]))))
    a("")
    a("Official data only (EIA, FHWA, EPA, World Bank, Ember). Every number traced to a file hash.")
    a("[live link] [repo link] #HydraDB")
    a("```")
    a("")
    a("## Form answers draft")
    a("")
    a("- **Track:** 1, a graph that improves itself.")
    a("- **One line:** A HydraDB graph links crude oil, gasoline, driving, EVs, fuel use and transport CO2, and refits every link each year; tested against a vector-store baseline under a rule written before the first run.")
    a("- **How HydraDB is used:** link weights, fit state, per-year link history and predictions are HydraDB nodes; each prediction is a graph walk (`<-[:INTO]-`) plus anchored id reads; refits are written back before the next year.")
    a("- **Metric:** MAE of the yearly change in U.S. transport CO2, holdout 2005–2024 (n=%d), walk-forward." % sc["graph"]["holdout_n"])
    a("- **Result:** %s; graph %s vs no change %s, k-NN %s, frozen %s. Fragile: depends on 2020–21." % (r["verdict"], g, nc, kn, fr))
    a("")
    return "\n".join(L)


def main():
    with open(README, "w", encoding="utf-8", newline="\n") as f:
        f.write(render())
    os.makedirs(os.path.dirname(LAUNCH), exist_ok=True)
    with open(LAUNCH, "w", encoding="utf-8", newline="\n") as f:
        f.write(render_launch())
    print("README.md and docs/LAUNCH.md written")


if __name__ == "__main__":
    main()
